# Defaults for vpn-tether.sh. Do not edit this file if you want your settings to survive a
# module update: put overrides in /data/adb/vpn-tether.conf instead (same syntax, read after this one).

# Hotspot interface(s), space separated, e.g. "wlan1" or "wlan1 rndis0".
# Empty = auto-detect from the system's tethering rule (ip rule, priority 21000).
HS=""

# VPN interface, e.g. "tun0". Empty = auto-detect (first tun*/wg*/ppp*/tap* interface that has a default route).
TUN=""

# DNS server that hotspot clients' DNS queries are redirected to.
#   auto       = if the VPN interface has a /30 address (sing-box/NekoBox style 172.19.0.1/30),
#                use the other host of that /30 (172.19.0.2). Otherwise DNS redirect is skipped.
#   off        = do not touch DNS (clients' DNS will then leave through the uplink: a DNS leak).
#   a.b.c.d    = use this IPv4 address, reachable through the VPN.
VPN_DNS=auto
